/// Determines whether an 8-bit signed integer is prime under the definition:
/// result == (n >= 2 && for all k with 2 <= k < n, n mod k != 0)
pub fn is_prime(n: i8) -> bool {
    // Handle all values less than 2 (including negatives).
    if n < 2 {
        return false;
    }

    // Work in a wider type to avoid overflow in arithmetic/measure reasoning.
    let n16: i16 = n as i16;

    // Candidate divisor starts at 2 and increases.
    let mut k: i16 = 2;

    // Loop over all k with 2 <= k < n.
    while k < n16 {
        // Loop invariants (informal, for specification/proof obligations):
        // 1) n16 >= 2
        // 2) 2 <= k && k <= n16
        // 3) For all j with 2 <= j < k, n16 % j != 0

        if n16 % k == 0 {
            // Found a divisor in [2, n), so n is not prime.
            return false;
        }

        // Termination measure (well-founded, strictly decreasing):
        // measure = n16 - k
        // Each iteration increments k by 1, so (n16 - k) decreases by 1.
        k += 1;
    }

    // If we completed the loop, then for all k with 2 <= k < n, n % k != 0,
    // and since n >= 2, n is prime by the given definition.
    true
}